import{c as t,Q as a,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"ClaudeDevs：Claude Code Dynamic Workflows 官方發布（Research Preview）","description":"","frontmatter":{"url":"https://x.com/ClaudeDevs/status/2060044853279617150","title":"ClaudeDevs：Claude Code Dynamic Workflows 官方發布（Research Preview）","author":"ClaudeDevs","archived":"2026-06-15T00:00:00.000Z","handle":"@ClaudeDevs","published":"2026-05-28T00:00:00.000Z","score":"8.0/10","stats":"10,503 likes · 946 retweets","tags":["dynamic-workflows","claude-code","subagents","parallel","announcement","research-preview"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-05-28-@ClaudeDevs-617150.md","filePath":"research/tweets/2026-05-28-@ClaudeDevs-617150.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-05-28-@ClaudeDevs-617150.md"};function d(l,e,n,c,i,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="claudedevs-claude-code-dynamic-workflows-官方發布-research-preview" tabindex="-1">ClaudeDevs：Claude Code Dynamic Workflows 官方發布（Research Preview） <a class="header-anchor" href="#claudedevs-claude-code-dynamic-workflows-官方發布-research-preview" aria-label="Permalink to &quot;ClaudeDevs：Claude Code Dynamic Workflows 官方發布（Research Preview）&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/ClaudeDevs/status/2060044853279617150" target="_blank" rel="noreferrer">https://x.com/ClaudeDevs/status/2060044853279617150</a><strong>作者</strong>：ClaudeDevs（@ClaudeDevs） <strong>發布日期</strong>：2026-05-28 <strong>收錄日期</strong>：2026-06-15 <strong>類型</strong>：tweet <strong>統計</strong>：10,503 likes · 946 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>New in Claude Code (research preview): dynamic workflows.</p><p>Claude writes an orchestration script on the fly, then spins up a large fleet of coordinated subagents in parallel to take on your most complex tasks.</p><p>Use the word &quot;workflow&quot; in a prompt to get started.</p><p>Or enable ultracode mode (/effort ultracode) for automatic workflow creation on complex tasks.</p><p>What this unlocks: → Migrations touching hundreds of files → Codebase-wide audits → Parallel test generation → Multi-agent research synthesis</p><p>The orchestration script is saved, so workflows are reusable.</p><p>Docs: claude.ai/code/workflows</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>直接告知觸發詞 &quot;workflow&quot; 和 /effort ultracode 指令，立即可操作</td></tr><tr><td>B. 創新性 (20%)</td><td>8/10</td><td>官方首發，但內容屬功能說明而非深度分析</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>有具體使用場景列表，但無量化數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>概念完整但未提供架構細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用所有 Claude Code 用戶，涵蓋多種任務類型</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.0/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：直接提供觸發詞與場景清單，適合整合進 dynamic-workflows SKILL 的使用指引。</p>',15)])])}const w=t(o,[["render",d]]);export{p as __pageData,w as default};
